struct tok {
	u_int v;		/* value */
	const char *s;		/* string */
};

struct netdissect_options {
  int ndo_bflag;
  int ndo_eflag;
  int ndo_fflag;
  int ndo_gflag;
  int ndo_Kflag;
  int ndo_nflag;
  int ndo_Nflag;
  int ndo_qflag;
  int ndo_Sflag;
  int ndo_tflag;
  int ndo_uflag;
  int ndo_vflag;
  int ndo_xflag;
  int ndo_Xflag;
  int ndo_Aflag;
  int ndo_Hflag;
  const char *ndo_protocol;
  jmp_buf ndo_early_end;
  void *ndo_last_mem_p;
  int ndo_packet_number;
  int ndo_lengths;
  int ndo_print_sampling;
  int ndo_suppress_default_print;
  int ndo_tstamp_precision;
  const char *program_name;

  char *ndo_espsecret;
  struct sa_list *ndo_sa_list_head;
  struct sa_list *ndo_sa_default;

  char *ndo_sigsecret;

  int   ndo_packettype;

  int   ndo_snaplen;
  int   ndo_ll_hdr_len;

  const u_char *ndo_packetp;
  const u_char *ndo_snapend;

  struct netdissect_saved_packet_info *ndo_packet_info_stack;

  if_printer ndo_if_printer;

  void (*ndo_default_print)(netdissect_options *,
			    const u_char *bp, u_int length);

  int  (*ndo_printf)(netdissect_options *,
		     const char *fmt, ...)
		     PRINTFLIKE_FUNCPTR(2, 3);
  void NORETURN_FUNCPTR (*ndo_error)(netdissect_options *,
			     status_exit_codes_t status,
			     const char *fmt, ...)
			     PRINTFLIKE_FUNCPTR(3, 4);
  void (*ndo_warning)(netdissect_options *,
		      const char *fmt, ...)
		      PRINTFLIKE_FUNCPTR(2, 3);
};

struct netdissect_saved_packet_info {
  u_char *ndspi_buffer;
  const u_char *ndspi_packetp;
  const u_char *ndspi_snapend;
  struct netdissect_saved_packet_info *ndspi_prev;
};

struct lladdr_info {
	const char *(*addr_string)(netdissect_options *, const u_char *);
	const u_char *addr;
};

struct cksum_vec {
	const uint8_t	*ptr;
	int		len;
};

struct uint_tokary
{
	u_int uintval;
	const struct tok *tokary;
};

